import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { accessFor, filterCommands, paletteCommands, SCREEN_FOR, type PaletteCommand } from './model';

/** The server's OpenAPI document for the real command registry (regenerated by the Rust openapi_surfaces test). */
const fixture = JSON.parse(
  readFileSync(fileURLToPath(new URL('../../tests/fixtures/openapi.json', import.meta.url)), 'utf8'),
) as Record<string, unknown>;

/** Every operation in the document, read directly from it, so the palette is checked against the source. */
function operationsOf(doc: Record<string, unknown>): { method: string; path: string; op: Record<string, unknown> }[] {
  const out: { method: string; path: string; op: Record<string, unknown> }[] = [];
  for (const [path, item] of Object.entries(doc.paths as Record<string, Record<string, Record<string, unknown>>>)) {
    for (const [method, op] of Object.entries(item)) out.push({ method, path, op });
  }
  return out;
}

const commands = paletteCommands(fixture);
const byName = (name: string): PaletteCommand => {
  const found = commands.find((command) => command.command === name);
  if (!found) throw new Error(`no palette command ${name}`);
  return found;
};

describe('command palette list, generated from the OpenAPI document', () => {
  it('lists every operation of the document, once', () => {
    const operations = operationsOf(fixture);
    expect(commands).toHaveLength(operations.length);
    expect(new Set(commands.map((c) => c.command)).size).toBe(commands.length);
    expect(operations.length).toBeGreaterThan(0);
  });

  it.each(operationsOf(fixture).map((o) => [o.op['x-ledgers-command'] as string, o] as const))(
    '%s appears with its CLI, MCP tool and HTTP call',
    (name, { method, path, op }) => {
      const command = byName(name);
      // All three equivalents come from the document, verbatim.
      expect(command.cli).toBe(op['x-ledgers-cli']);
      expect(command.cli).toMatch(/^ledgers [a-z0-9-]+( [a-z0-9-]+)*$/);
      expect(command.mcp).toBe(op['x-ledgers-mcp']);
      // Human-only commands publish no MCP tool; every other one publishes its name.
      expect(command.mcp).toBe(op['x-ledgers-human-only'] === true ? null : name.replace(/\./g, '_'));
      expect(command.method).toBe(method.toUpperCase());
      expect(command.path).toBe(path);
      expect(command.curl).toBe(op['x-ledgers-curl']);
      expect(command.curl).toContain(path);
      expect(command.tier).toBe(op['x-ledgers-tier']);
    },
  );

  it('keeps a command without a published CLI or MCP form visible, with the gap empty', () => {
    const doc = structuredClone(fixture) as { paths: Record<string, Record<string, Record<string, unknown>>> };
    doc.paths['/v1/x'] = { post: { operationId: 'x_y', 'x-ledgers-command': 'x.y', 'x-ledgers-tier': 'draft', 'x-ledgers-human-only': true } };
    const listed = paletteCommands(doc).find((command) => command.command === 'x.y');
    expect(listed).toMatchObject({ cli: null, mcp: null, curl: null, humanOnly: true });
  });

  it('skips operations the document does not name as commands', () => {
    expect(paletteCommands({ paths: { '/v1/z': { get: { operationId: 'z' } } } })).toEqual([]);
    expect(paletteCommands(null)).toEqual([]);
  });

  it('filters by any form: the CLI line, the MCP tool, the path', () => {
    expect(filterCommands(commands, 'ledgers entries').map((c) => c.command)).toEqual(
      expect.arrayContaining(['entries.list', 'entries.post', 'entries.reverse']),
    );
    expect(filterCommands(commands, 'reports_balance_sheet').map((c) => c.command)).toEqual(['reports.balance_sheet']);
    expect(filterCommands(commands, '/v1/accounts').map((c) => c.command)).toEqual(['accounts.list']);
    expect(filterCommands(commands, '   ')).toHaveLength(commands.length);
  });
});

describe('what a session may do with a command', () => {
  it('an owner or an admin runs a posting command and is taken to the entry form', () => {
    for (const roles of [['owner'], ['admin']]) {
      expect(accessFor(byName('entries.post'), { kind: 'person', roles })).toEqual({
        runnable: true,
        hash: '#/new',
        label: 'shell.new_entry',
      });
    }
  });

  it('a person without owner or admin may read, not post', () => {
    const viewer = { kind: 'person', roles: ['viewer'] } as const;
    expect(accessFor(byName('reports.trial_balance'), viewer)).toMatchObject({ runnable: true, hash: '#/reports' });
    expect(accessFor(byName('entries.post'), viewer)).toEqual({ runnable: false, reason: 'role' });
    expect(accessFor(byName('entries.reverse'), viewer)).toEqual({ runnable: false, reason: 'role' });
  });

  it('the approval commands are human-only: a person opens their inbox, an agent key is refused', () => {
    for (const name of ['approvals.list', 'approvals.decide', 'approvals.decide_bulk']) {
      expect(byName(name).humanOnly, name).toBe(true);
      expect(accessFor(byName(name), { kind: 'person', roles: ['owner'] })).toMatchObject({ runnable: true, hash: '#/approvals' });
      expect(accessFor(byName(name), { kind: 'key' }), name).toEqual({ runnable: false, reason: 'human-only' });
    }
  });

  it('an agent key runs the commands its tier allows; the server decides the rest', () => {
    expect(accessFor(byName('entries.post'), { kind: 'key' })).toMatchObject({ runnable: true });
  });

  it('a human-only command is refused to agent keys and says so', () => {
    const humanOnly: PaletteCommand = { ...byName('entries.post'), command: 'policy.put_key', humanOnly: true, mcp: null };
    expect(accessFor(humanOnly, { kind: 'key' })).toEqual({ runnable: false, reason: 'human-only' });
  });

  it('a command with no screen in this app is API and CLI only', () => {
    const unknown: PaletteCommand = { ...byName('entries.post'), command: 'approvals.status' };
    expect(accessFor(unknown, { kind: 'person', roles: ['owner'] })).toEqual({ runnable: false, reason: 'no-screen' });
  });

  it('every screen mapping names a command the registry has', () => {
    const names = new Set(commands.map((c) => c.command));
    for (const name of Object.keys(SCREEN_FOR)) {
      if (name === 'bills.match') continue; // offered only by servers that serve bills.match
      expect(names.has(name), name).toBe(true);
    }
  });
});
